import { XMLParser } from 'fast-xml-parser';

// Flag definitions for HWi32_Init
export const HWi_FLAG_DEBUG_MODE_ENABLE = 1 << 0; // Enable Debug Mode
export const HWi_FLAG_SW_SMI_ENABLE = 1 << 1; // Enable SW SMI

export const HWi_FLAG_IDE_SAFE = 0 << 2; // Use Safe IDE Mode (recommended)
export const HWi_FLAG_IDE_ADR_1 = 1 << 2; // Enable Low-level IDE scan up-to Device #1
export const HWi_FLAG_IDE_ADR_2 = 2 << 2; // Enable Low-level IDE scan up-to Device #2
export const HWi_FLAG_IDE_ADR_4 = 4 << 2; // Enable Low-level IDE scan up-to Device #4

export const HWi_FLAG_PROB_PCI_SCAN = 1 << 5; // Check Problematic PCI devices (0=skip them)
export const HWi_FLAG_SMBUS_ENABLE = 1 << 6; // Enable SMBus support
export const HWi_FLAG_EC_DISABLE = 1 << 7; // Disable Embedded Controller support
export const HWi_FLAG_HPET_DISABLE = 1 << 8; // Disable using of High-Precision Event Timers
export const HWi_FLAG_GPU_I2C_DISABLE = 1 << 10; // Disable support of GPU I2C
export const HWi_FLAG_IOCTL_KERNEL = 1 << 11; // Enable routing IOCTLs via kernel
export const HWi_FLAG_PERSISTENT_DRIVER = 1 << 12; // Enable Persistent Driver
export const HWi_FLAG_DRIVE_SCAN_DISABLE = 1 << 13; // Disable entire Drive Scan
export const HWi_FLAG_PCI_DIRECT = 1 << 14; // Enable Low-level PCI Scan
export const HWi_FLAG_CSMI_SAS_DISABLE = 1 << 15; // Disable CSMI-SAS support
export const HWi_FLAG_IME_DISABLE = 1 << 16; // Disable Intel Management Engine Support
export const HWi_FLAG_GPU_WAKE_EXT = 1 << 17; // Perform Extended GPU wake-up method for disabled secondary GPUs
export const HWi_FLAG_PREFER_ADL = 1 << 18; // 1=report certain AMD GPU parameters (e.g. clocks, utilization) from AMD GPU driver (ADL) instead of direct-access
export const HWi_FLAG_CORSAIR_ASETEK = 1 << 19; // 1=Support Corsair/Asetek coolers
export const HWi_FLAG_SNAPSHOT_POLLING = 1 << 20; // 1=Enable Snapshot polling mode [AMD Zen only]

// This is the recommended default setting
export const HWi_FLAG_DEFAULT =
  HWi_FLAG_EC_DISABLE | // 官方推荐0X40
  HWi_FLAG_SMBUS_ENABLE | // Enable SMBus support
  HWi_FLAG_CORSAIR_ASETEK; // Support Corsair/Asetek coolers

const hwinfoAddon = require('bindings')('hwinfoAddon');

const hwinfo = new hwinfoAddon.hwinfo();

export async function init(flag = HWi_FLAG_DEFAULT): Promise<boolean> {
  return hwinfo.init(flag);
}

export function isInited(): boolean {
  return hwinfo.isInited();
}

export async function status(): Promise<Object> {
  const statusJson = await hwinfo.status();
  if (statusJson === '') {
    return {};
  }

  return JSON.parse(statusJson);
}

export async function details(): Promise<Object> {
  const detailsXmlString = await hwinfo.details();
  return new Promise((resolve, rejects) => {
    if (detailsXmlString === '') {
      return resolve({});
    }
    const xmlParser = new XMLParser();
    const detailsRootObj = xmlParser.parse(detailsXmlString);
    if (
      detailsRootObj &&
      'HWINFO' in detailsRootObj &&
      detailsRootObj['HWINFO'] &&
      'COMPUTER' in detailsRootObj['HWINFO']
    ) {
      return resolve(detailsRootObj['HWINFO']['COMPUTER']);
    } else {
      return resolve({});
    }
  });
}

export function setStatusFilter(keyword: string): void {
  hwinfo.setStatusFilter(keyword);
}

export function setMaxSensorTimeout(timeout: number): void {
  hwinfo.setMaxSensorTimeout(timeout);
}

export function setLogHandler(callback: (error: Error, msg: string) => void): void {
  // TODO: 看怎么把日志传出来
  hwinfo.setLogHandler(callback);
}

export function deInit() {
  hwinfo.deInit();
}
